{
  "name": "实验数据桶存储组件",
  "name_en": "Tub datastore",
  "manufacturer": "",
  "description": "用于实验过程中的非物理数据存储组件。它以键值格式保存传感器数据、数值、图像和数组记录，并将记录写入 JSON 与外部文件，便于后续读取、校验、筛选和整理训练数据集。",
  "description_en": "A non-physical datastore component for experiments. It stores sensor values, numeric data, images, and arrays in key-value records, writing data to JSON plus external files for later reading, validation, filtering, and training dataset curation.",
  "tag_hints": [
    "experiment data logging",
    "sensor record storage",
    "image dataset storage",
    "JSON record files",
    "training data curation",
    "record exclusion management",
    "DonkeyCar Tub"
  ],
  "actions": [
    {
      "action_name": "auto-update_df",
      "description": "更新已存储记录的内部数据表视图。",
      "description_en": "Update the internal dataframe view of stored records."
    },
    {
      "action_name": "auto-write_json_record",
      "description": "将一条记录写入 JSON 文件。",
      "description_en": "Write a record to a JSON file."
    },
    {
      "action_name": "auto-make_record_paths_absolute",
      "description": "将记录中的文件路径转换为绝对路径。",
      "description_en": "Convert file paths in a record to absolute paths."
    },
    {
      "action_name": "auto-check",
      "description": "检查所有记录是否可正常加载，并可选择修复或移除异常记录。",
      "description_en": "Check whether all records can be loaded, optionally fixing or removing bad records."
    },
    {
      "action_name": "auto-remove_record",
      "description": "移除一条记录及其关联数据文件。",
      "description_en": "Remove a record and its associated data files."
    },
    {
      "action_name": "auto-put_record",
      "description": "存入一条记录，并在需要时将图像或数组等数据另存为文件。",
      "description_en": "Store a record, saving images or arrays as separate files when needed."
    },
    {
      "action_name": "auto-erase_last_n_records",
      "description": "从磁盘删除最近的 N 条记录。",
      "description_en": "Erase the last N records from disk."
    },
    {
      "action_name": "auto-erase_record",
      "description": "删除指定索引的记录。",
      "description_en": "Erase the record at the specified index."
    },
    {
      "action_name": "auto-read_record",
      "description": "读取一条记录，并加载其外部保存的对象数据。",
      "description_en": "Read a record and load objects saved in external files."
    },
    {
      "action_name": "auto-gather_records",
      "description": "收集当前数据桶中的全部记录。",
      "description_en": "Gather all records from the datastore."
    },
    {
      "action_name": "auto-make_file_name",
      "description": "为指定键、扩展名和索引生成文件名。",
      "description_en": "Generate a filename for a given key, extension, and index."
    },
    {
      "action_name": "auto-delete",
      "description": "删除整个数据桶目录及其文件。",
      "description_en": "Delete the entire datastore folder and its files."
    },
    {
      "action_name": "auto-shutdown",
      "description": "关闭该数据存储组件。",
      "description_en": "Shut down the datastore component."
    },
    {
      "action_name": "auto-excluded",
      "description": "检查指定索引是否被排除。",
      "description_en": "Check whether a specified index is excluded."
    },
    {
      "action_name": "auto-exclude_index",
      "description": "将指定索引标记为排除。",
      "description_en": "Mark a specified index as excluded."
    },
    {
      "action_name": "auto-include_index",
      "description": "将指定索引从排除列表中恢复包含。",
      "description_en": "Re-include a specified index by removing it from the exclusion list."
    },
    {
      "action_name": "auto-write_exclude",
      "description": "将排除索引列表写入文件。",
      "description_en": "Write the exclusion index list to a file."
    }
  ]
}

